class Solution {
  public boolean checkValidCuts(int n, int[][] rectangles) {
    return groups(rectangles, 0, 2) >= 3 || groups(rectangles, 1, 3) >= 3;
  }

  // number of groups of rectangles that cannot be separated by a cut along one axis
  private int groups(int[][] rectangles, int startIdx, int endIdx) {
    int[][] sorted = rectangles.clone();
    Arrays.sort(sorted, (a, b) -> Integer.compare(a[startIdx], b[startIdx]));
    int groups = 0;
    long reach = -1;
    for (int[] r : sorted) {
      if (r[startIdx] >= reach) groups++;
      reach = Math.max(reach, r[endIdx]);
    }
    return groups;
  }
}
